import{_ as i,c as s,a2 as t,o}from"./chunks/framework.BQmytedh.js";const r="/assets/CreateSuperviseTab.CEYnTcna.png",a="/assets/BrowseUserEditSupervision.DDKOWU21.png",n="/assets/CreateSupervisedUsersTree.QdCJ45Ps.png",l="/assets/CreatePublishOnBehalf.Ces0MhB9.png",c="/assets/BrowseCollectionManagement.CH9C-Zd4.png",f=JSON.parse('{"title":"Supervise Feature (Available on next version)","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/supervise-feature.md","filePath":"doc/guides/usage/supervise-feature.md"}'),u={name:"doc/guides/usage/supervise-feature.md"};function p(d,e,h,g,v,m){return o(),s("div",null,e[0]||(e[0]=[t('<h1 id="supervise-feature-available-on-next-version" tabindex="-1">Supervise Feature <small>(Available on next version)</small> <a class="header-anchor" href="#supervise-feature-available-on-next-version" aria-label="Permalink to &quot;Supervise Feature &lt;small&gt;(Available on next version)&lt;/small&gt;&quot;">​</a></h1><p>The Supervise feature in ioChem-BD enables research group leaders, principal investigators, or designated supervisors to oversee and manage the work of their team members.</p><p>Supervisors can access all content from supervised users, assist with publication workflows, and manage published collections on their behalf.</p><p><img src="'+r+'" alt="Supervise tab in Create module"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Supervise feature provides research group leaders with enhanced oversight and control capabilities:</p><ul><li><strong>Complete visibility</strong> - Access all projects and calculations from supervised users</li><li><strong>Publication assistance</strong> - Publish content on behalf of supervised users</li><li><strong>Collection management</strong> - Manage published collections in Browse module</li><li><strong>Administrative control</strong> - Lift embargoes, generate reviewer links, and update metadata</li></ul><h2 id="setting-up-supervision" tabindex="-1">Setting Up Supervision <a class="header-anchor" href="#setting-up-supervision" aria-label="Permalink to &quot;Setting Up Supervision&quot;">​</a></h2><p>Supervision relationships are configured in the <strong>Browse module</strong> by system administrators. The supervisor assignment is performed on the user edition page.</p><p><img src="'+a+'" alt="Browse user edition page with supervisor assignment"></p><p>To assign a supervisor to a user:</p><ol><li>Navigate to the <strong>Browse module</strong> administration panel.</li><li>Access the <strong>Users</strong> management section.</li><li>Select the user who will have the supervisor role.</li><li>Click <strong>Edit</strong> to open the user edition form.</li><li>In the <em>Belongs to group</em> secton, mark the <strong>Supervisor</strong> checkbox to select the designated supervisor for a specific group.</li><li>Click <strong>Save</strong> to activate the supervision relationship.</li></ol><p>Once configured, the supervisor will immediately gain access to all the supervised users group content in the Create module.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A supervisor can oversee multiple users and user groups.Supervision relationships can be modified at any time by administrators.</p></div><h2 id="accessing-supervised-content" tabindex="-1">Accessing Supervised Content <a class="header-anchor" href="#accessing-supervised-content" aria-label="Permalink to &quot;Accessing Supervised Content&quot;">​</a></h2><p>Supervisors access supervised users&#39; content through a dedicated interface in the <strong>Create module</strong>. When logged in as a supervisor, you&#39;ll see an additional section displaying all supervised users organized by research group.</p><p><img src="'+n+'" alt="Supervised users tree in Create module"></p><p>The supervised content view is organized hierarchically:</p><ul><li><strong>Research Groups</strong> - Top-level organization of your supervised users</li><li><strong>Supervised Users</strong> - Individual users under your supervision</li><li><strong>Projects</strong> - All projects belonging to each supervised user</li><li><strong>Calculations</strong> - Individual calculations within projects</li></ul><p>To work with supervised content:</p><ol><li>Navigate to the supervised users section in Create</li><li>Expand the research group to see supervised users</li><li>Expand a user to see their complete project hierarchy</li><li>Click on any project or calculation to view its details</li></ol><p>The <strong>Item Actions</strong> and <strong>Item Details</strong> frames will display the selected element&#39;s information, just as if you were the owner.</p><h2 id="supervisor-permissions" tabindex="-1">Supervisor Permissions <a class="header-anchor" href="#supervisor-permissions" aria-label="Permalink to &quot;Supervisor Permissions&quot;">​</a></h2><p>Supervisors have <strong>enhanced permissions</strong> that exceed standard collaboration access. A supervisor has all the capabilities of FULL ACCESS collaboration, plus additional administrative powers:</p><h3 id="standard-full-access-capabilities" tabindex="-1">Standard FULL ACCESS Capabilities <a class="header-anchor" href="#standard-full-access-capabilities" aria-label="Permalink to &quot;Standard FULL ACCESS Capabilities&quot;">​</a></h3><ul><li>View all project structures and calculations</li><li>Download calculation files</li><li>View 3D structures and results</li><li>Generate reports</li><li>Create new subprojects and calculations</li><li>Upload new calculations</li><li>Modify project and calculation metadata</li><li>Delete any element, excluding shared entities</li></ul><h3 id="additional-supervisor-capabilities" tabindex="-1">Additional Supervisor Capabilities <a class="header-anchor" href="#additional-supervisor-capabilities" aria-label="Permalink to &quot;Additional Supervisor Capabilities&quot;">​</a></h3><ul><li><strong>Publish on behalf of supervised users</strong> - Initiate publication workflows using the supervised user&#39;s identity</li><li><strong>Access Browse collection edition page</strong> - Manage published collections in the Browse module</li><li><strong>Define publication metadata</strong> - Edit collection descriptions, keywords, and other metadata</li><li><strong>Lift embargoes</strong> - Make embargoed collections publicly accessible before scheduled date</li><li><strong>Generate reviewer links</strong> - Create special access URLs for peer review processes</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>With great power comes great responsibility. Supervisors should use their elevated permissions ethically and in accordance with institutional policies.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Published projects and collections cannot be modified or removed, regardless of permission level. Once a project has been published to the Browse module, it becomes read-only for all users including the owner and supervisor.</p></div><h2 id="publishing-on-behalf-of-supervised-users" tabindex="-1">Publishing on Behalf of Supervised Users <a class="header-anchor" href="#publishing-on-behalf-of-supervised-users" aria-label="Permalink to &quot;Publishing on Behalf of Supervised Users&quot;">​</a></h2><p>One of the most powerful supervisor capabilities is the ability to publish content on behalf of supervised users. This is particularly useful when:</p><ul><li>Assisting less experienced researchers with the publication process</li><li>Ensuring quality control before public release</li><li>Meeting publication deadlines when the user is unavailable</li><li>Streamlining group-wide publication workflows</li></ul><p><img src="'+l+'" alt="Publish on behalf action"></p><p>To publish on behalf of a supervised user:</p><ol><li>Navigate to the supervised user&#39;s content</li><li>Select the project or calculation to publish</li><li>Right-click and select <strong>Publish on behalf</strong> from the context menu</li><li>The publication form will open with the supervised user&#39;s identity</li><li>Complete the publication workflow as you would for your own content</li><li>The publication will be attributed to the supervised user, not the supervisor</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When publishing on behalf, all publication metadata (author, submitter, etc.) will reflect the supervised user&#39;s information, maintaining proper attribution.</p></div><h2 id="managing-published-collections" tabindex="-1">Managing Published Collections <a class="header-anchor" href="#managing-published-collections" aria-label="Permalink to &quot;Managing Published Collections&quot;">​</a></h2><p>Supervisors can access and manage published collections in the <strong>Browse module</strong> for all supervised users. This includes full administrative control over collection settings and visibility.</p><p><img src="'+c+'" alt="Browse collection management for supervised users"></p><p>Available collection management actions:</p><h3 id="edit-collection-metadata" tabindex="-1">Edit Collection Metadata <a class="header-anchor" href="#edit-collection-metadata" aria-label="Permalink to &quot;Edit Collection Metadata&quot;">​</a></h3><ul><li>Update collection title and description</li><li>Update related publications and funding information</li></ul><h3 id="embargo-management" tabindex="-1">Embargo Management <a class="header-anchor" href="#embargo-management" aria-label="Permalink to &quot;Embargo Management&quot;">​</a></h3><p>Supervisors can control embargo settings:</p><ul><li>View current embargo status</li><li>Lift embargoes immediately when appropriate</li></ul><h3 id="reviewer-access" tabindex="-1">Reviewer Access <a class="header-anchor" href="#reviewer-access" aria-label="Permalink to &quot;Reviewer Access&quot;">​</a></h3><p>Generate special access links for peer review:</p><ul><li>Share embargoed content with selected reviewers</li><li>Track reviewer access activity</li></ul><p>To access collection management:</p><ol><li>Log in to the <strong>Browse module</strong></li><li>Navigate to the supervised user&#39;s collections</li><li>Select the collection to manage</li><li>Click <strong>Edit Collection</strong> icon to access the management interface</li><li>Make necessary changes</li><li>Click <strong>Save</strong> to apply updates</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All actions performed by supervisors are logged for audit purposes, maintaining transparency and accountability.</p></div><h2 id="best-practices-for-supervisors" tabindex="-1">Best Practices for Supervisors <a class="header-anchor" href="#best-practices-for-supervisors" aria-label="Permalink to &quot;Best Practices for Supervisors&quot;">​</a></h2><p>When working with supervised users&#39; content:</p><ol><li><strong>Communicate clearly</strong> - Inform supervised users when you access or modify their content</li><li><strong>Respect autonomy</strong> - Use publish-on-behalf sparingly; encourage users to publish independently when possible</li><li><strong>Maintain quality</strong> - Review content before publication to ensure it meets institutional standards</li><li><strong>Document actions</strong> - Keep records of significant changes or publications performed on behalf</li><li><strong>Train users</strong> - Use supervision as an opportunity to mentor users on proper workflows</li><li><strong>Follow policies</strong> - Adhere to your institution&#39;s data management and publication policies</li></ol><h2 id="supervision-vs-collaboration" tabindex="-1">Supervision vs. Collaboration <a class="header-anchor" href="#supervision-vs-collaboration" aria-label="Permalink to &quot;Supervision vs. Collaboration&quot;">​</a></h2><p>While both features enable teamwork, they serve different purposes:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Supervision</th><th>Collaboration</th></tr></thead><tbody><tr><td><strong>Relationship</strong></td><td>Hierarchical (supervisor/supervised)</td><td>Peer-to-peer</td></tr><tr><td><strong>Setup</strong></td><td>Configured in Browse by admin</td><td>Initiated by project owner</td></tr><tr><td><strong>Scope</strong></td><td>All user&#39;s group content</td><td>Specific shared projects</td></tr><tr><td><strong>Permissions</strong></td><td>FULL ACCESS + publish on behalf + Browse management</td><td>READ, WRITE, or FULL ACCESS</td></tr><tr><td><strong>Use Case</strong></td><td>Group oversight, quality control</td><td>Project-specific teamwork</td></tr><tr><td><strong>Attribution</strong></td><td>Can publish as supervised user</td><td>Always publishes as self</td></tr></tbody></table><p>Choose <strong>Supervision</strong> when you need comprehensive oversight of a user&#39;s research output. Choose <strong>Collaboration</strong> when working together on specific projects as peers.</p>',59)]))}const w=i(u,[["render",p]]);export{f as __pageData,w as default};
